// La carte de l'image du programme : chaque octet de ce que le moteur garde de MAIN.EXE
// (image-programme.js) rangé dans une zone nommée et typée ; l'extraction (assets-du-jeu.js) la suit
// pour écrire les tables lisibles de assets/programme/ (tables-du-programme.js, qui dit les types).
//
// FAIT PAR outils/carte-du-programme.mjs, d'après les références du code aux données (le
// désassemblage de MAIN.EXE : chaque accès à une adresse fixe, sa largeur, chaque adresse prise,
// chaque pointeur logé dans les données), les constantes d'adresses du code lisible (moteur/jeu :
// les noms, les commentaires, les modules qui lisent chaque zone) et les tables décrites à la main
// (outils/tables-connues.mjs). Le refaire plutôt que de retoucher ici.
//
// Une zone : [adresse, taille, type, nom, fichier (dans assets/programme/ ; null : des zéros ; « ../ » :
// un autre asset, les polices, images/polices/),
// lecteurs (les modules de moteur/jeu qui la lisent, le plus assidu d'abord), description, brute
// (son sens n'est pas établi : ses octets tels quels)].

const deplier = (z) => ({ adresse: z[0], taille: z[1], type: z[2], nom: z[3], fichier: z[4], lecteurs: z[5], description: z[6], brut: !!z[7] });

